        if abs(ans) < eps:
            return f(x, y, z) > -eps
        return abs(ans - f(x, y, z)) / abs(ans) < eps

    def chg(ans, x, y, z):
        if abs(ans) < eps:
            return g(x, y, z) > -eps
        return abs(ans - g(x, y, z)) / abs(ans) < eps
    ans = decimal.Decimal(0)
    ans = max(f(x, y, z), f(x, z, y), f(y, x, z), f(y, z, x), f(z, x, y), f(z, y, x))
