    def isConvex(Points):
        n = len(Points)
        for i in range(n):
            if ccw(Points[i - 1], Points[i], Points[(i + 1) % n]) == -1:
                return False
        return True

    def ConvexHull(Points):
        Points.sort(key=lambda p: p.y)
        Points.sort(key=lambda p: p.x)
        Qs = []
        for p in Points:
            while len(Qs) > 1 and ccw(Qs[-2], Qs[-1], p) == -1:
                Qs.pop()
            Qs.append(p)
        t = len(Qs)
        Qs.pop()
        for p in reversed(Points):
            while len(Qs) > t and ccw(Qs[-2], Qs[-1], p) == -1:
                Qs.pop()
            Qs.append(p)
        Qs.pop()
        return Qs
