            self.y = y

        def inner_product(self, vec):
            return self.x * vec.x + self.y * vec.y

        def outer_product(self, vec):
            return self.x * vec.y - self.y * vec.x

        def norm(self):
            return math.sqrt(self.x ** 2 + self.y ** 2)
