def _main():

    def solve(n, k, M, t):
        task_sum = sum(t)
        t = sorted(t)
        best = 0
        for tasks_completed in range(n + 1):
            minutes_spent_on_full_tasks = tasks_completed * task_sum
            if minutes_spent_on_full_tasks > M:
                break
            total_points = tasks_completed * k + tasks_completed
            remaining_time = M - minutes_spent_on_full_tasks
            for subtask_time in t:
                subtasks_left = n - tasks_completed
                smaller_subtasks_time = subtasks_left * subtask_time
                if smaller_subtasks_time <= remaining_time:
                    remaining_time -= smaller_subtasks_time
                    total_points += subtasks_left
                else:
                    total_points += remaining_time // subtask_time
                    break
            best = max(total_points, best)
        return best

    def main():
        (n, k, M) = [int(x) for x in input().split(' ')]
        t = [int(x) for x in input().split(' ')]
        res = solve(n, k, M, t)
        print(res)
    if __name__ == '__main__':
        main()
_main()

