                s.append(c)
        return ''.join(s)

    def func_by_M(t):
        s = []
        for c in t:
            try:
                integer = int(c)
                s.append(str((integer + 1) % 10))
            except:
                s.append(c)
        return ''.join(s)

    def solve(s, t):
