                    if j <= m:
                        return _get(l, m, p * 2)
                    elif i >= m:
                        return _get(m, r, p * 2 + 1)
                    else:
                        return self.f(_get(l, m, p * 2), _get(m, r, p * 2 + 1))
            return _get(0, self.ln, 1)

