            ans = ''
            for i in range(26):
                ans += chr(i + 97) * lcopy[i]
            return ans
        ans = ''
        for i in range(ord(toexceed) - 97 + 1, 26):
            if lcopy[i] > 0:
                ans += chr(i + 97)
                lcopy[i] -= 1
                break
        return ans + arrange(lcopy)

    def operation(s1, s2):
