        for letter in s1:
            first_count[ord(letter) - 97] += 1
        common = 0
        lcopy = list(first_count)
        for i in range(len(s2)):
            letter = s2[i]
            num = ord(letter) - 97
            if lcopy[num] > 0:
                lcopy[num] -= 1
                common += 1
            else:
                break
        found = False
        ans = ''
        for cval in range(common, -1, -1):
            if cval >= len(s1):
                lcopy[ord(s2[cval - 1]) - 97] += 1
                continue
            elif cval == len(s2):
                found = True
                ans = s2[:cval] + arrange(lcopy)
                break
            elif findmin(lcopy, s2[cval]):
                found = True
                ans = s2[:cval] + arrange(lcopy, s2[cval])
                break
            else:
                lcopy[ord(s2[cval - 1]) - 97] += 1
        if not found:
            return -1
        else:
            return ans
