        (x, y) = (0, 0)
        for i in range(1, m):
            if (i * n - d) % m == 0:
                x = i
                y = (i * n - d) // m
                if y == 0:
                    x += 1
                    y += 1
                break
        common = {}
        common_count = 0
        colors = {}
        for i in range(len(a)):
            colors[a[i]] = i
        for i in range(len(b)):
