        def pop(self, k):
            if self.debug:
                assert self.exist[k]
            L = self._left[k]
            R = self._right[k]
            if L != -1:
                if R != self.n:
                    (self._right[L], self._left[R]) = (R, L)
                else:
                    self._right[L] = self.n
            elif R != self.n:
