            if self.debug:
                assert self.exist[idx]
            res = idx
            while k:
                res = self._left[res]
                if res == -1:
                    break
                k -= 1
            return res

        def right(self, idx, k=1):
            if self.debug:
                assert self.exist[idx]
            res = idx
            while k:
                res = self._right[res]
                if res == self.n:
