def _main():

    class UnionFind:

        def __init__(self, num, V):
            self.par = [-1] * num
            self.unused = [0] * num
            self.cost = V

        def find(self, x):
            if self.par[x] < 0:
                return x
            else:
                x = self.par[x]
                return self.find(x)

        def union(self, x, y):
            rx = self.find(x)
            ry = self.find(y)
            if rx == ry:
                return 0
            if ry > rx:
                (rx, ry) = (ry, rx)
            self.par[ry] = rx
            self.cost[rx] += self.cost[ry]
            self.unused[rx] += self.unused[ry]
            self.unused[ry] = 0
            return 1

    def solve():
        (N, M) = map(int, input().split())
        X = list(map(int, sys.stdin.readline().split()))
