        t = [True] * slen
        for i in range(slen - 2, -1, -1):
            if s[i] > s[i + 1]:
                t[i] = False
            elif s[i] == s[i + 1]:
                t[i] = t[i + 1]
        lmss = []
        for i in range(1, slen):
            if not t[i - 1] and t[i]:
                lmss.append(i)
        seed = lmss
        sa = induced_sort(s, k, t, seed)
        new_sa = []
        for i in sa:
            if lms(t, i):
                new_sa.append(i)
        nums = dict()
        nums[new_sa[0]] = 0
        num = 0
        for o in range(len(new_sa) - 1):
            (i, j) = (new_sa[o], new_sa[o + 1])
            (diff, d) = (False, 0)
            for d in range(slen):
                if s[i + d] != s[j + d] or lms(t, i + d) != lms(t, j + d):
                    diff = True
                    break
                elif d > 0 and (lms(t, i + d) or lms(t, j + d)):
                    break
            if diff:
                num += 1
            nums[j] = num
        nums = list(map(lambda x: x[1], sorted(nums.items())))
        if num + 1 < len(nums):
            sa = sa_is(nums, num + 1)
        else:
            sa = [[]] * (max(nums) + 1)
            for (i, c) in enumerate(nums):
