        need = [0] * n
        for i in range(1, n):
            if cnt[i] != 0 and i > ruiseki_cnt[i]:
                need[i] = min(i - ruiseki_cnt[i], i)
        info = sorted(info, reverse=True)
        num = n - 1
        pos = 0
        q = []
        used_cnt = 0
        ans = 0
