import collections
import heapq

def _main():

    def constructGraph(n, edges):
        graph = collections.defaultdict(list)
        inDegree = [0 for _ in range(n)]
        for edge in edges:
            (a, b) = (edge[0] - 1, edge[1] - 1)
            graph[b].append(a)
            inDegree[a] += 1
        return [graph, inDegree]

    def solve(n, edges):
        (graph, inDegree) = constructGraph(n, edges)
        answer = [0 for _ in range(n)]
        pq = []
        for i in range(n):
            if inDegree[i] == 0:
                heapq.heappush(pq, -i)
        current = n
        while pq:
            currentNode = -heapq.heappop(pq)
            answer[currentNode] = current
            current -= 1
            if currentNode not in graph:
                continue
            for neighNode in graph[currentNode]:
                inDegree[neighNode] -= 1
                if inDegree[neighNode] == 0:
                    heapq.heappush(pq, -neighNode)
        return answer
    (n, m) = map(int, input().split())
    edges = []
    for _ in range(m):
        edges.append(list(map(int, input().split())))
    print(*solve(n, edges), sep=' ')
_main()

