def _main():

    def minimumCostSort(arr, arr_size):
        cost = 0
        sortarr = sorted(arr)
        cyclecontainer = []
        for i in range(arr_size):
            cycle = [arr[i]]
            next = sortarr.index(arr[i])
            while arr[next] != arr[i]:
                cycle += [arr[next]]
                next = sortarr.index(arr[next])
            cycle = sorted(cycle)
            if cycle not in cyclecontainer:
                cyclecontainer.append(cycle)
                if len(cycle) == 1:
                    pass
                elif len(cycle) == 2:
                    cost += sum(cycle)
                elif len(cycle) >= 3:
                    cost += min(sum(cycle) + (len(cycle) - 2) * min(cycle), sum(cycle) + min(cycle) + (len(cycle) + 1) * min(arr))
        return cost
    n = int(input())
    w = list(map(int, input().split()))
    print(minimumCostSort(w, n))
