from collections import deque

def _main():

    class heap:

        def __init__(self, k):
            self.heap = deque()
            self.len = 0
            self.k = k
            self.reversedheap = deque()

        def add(self, x):
            self.heap.appendleft(x)
            self.reversedheap.appendleft(x)
            self.len += 1
            self.standize()
            if self.len > self.k:
                self.pop()
                self.len = self.k

        def pop(self):
            self.heap.remove(self.reversedheap.popleft())

        def standize(self):
            t = 0
            k = self.len
            while 2 * t + 1 <= k - 1:
                if 2 * t + 2 > k - 1:
                    m = 2 * t + 1
                elif self.reversedheap[2 * t + 2] > self.reversedheap[2 * t + 1]:
                    m = 2 * t + 1
                else:
                    m = 2 * t + 2
                if self.reversedheap[t] > self.reversedheap[m]:
                    (self.reversedheap[m], self.reversedheap[t]) = (self.reversedheap[t], self.reversedheap[m])
                    t = m
                else:
                    break
            t = 0
            while 2 * t + 1 <= k - 1:
                if self.heap[t] < self.heap[2 * t + 1]:
                    (self.heap[2 * t + 1], self.heap[t]) = (self.heap[t], self.heap[2 * t + 1])
                    t = 2 * t + 1
                elif 2 * t + 2 <= k - 1 and self.heap[t] < self.heap[2 * t + 2]:
                    (self.heap[2 * t + 2], self.heap[t]) = (self.heap[t], self.heap[2 * t + 2])
                    t = 2 * t + 2
                else:
                    break

        def show(self, x):
            if x in set(self.heap):
                return 'YES'
            else:
                return 'NO'
    (n, k, q) = map(int, input().split())
    t = list(map(int, input().split()))
    online = heap(k)
    ans = []
    for i in range(q):
        (typei, idi) = map(int, input().split())
        if typei == 1:
            online.add(t[idi - 1])
        else:
            ans.append(online.show(t[idi - 1]))
    print('\n'.join(ans))
_main()

