def _main():

    def bi_search(a, x):
        n = len(a)
        (u, l) = (n, -1)
        while u - l > 1:
            md = (u + l) // 2
            if x > a[md]:
                l = md
            else:
                u = md
        return u

    class Bit:

        def __init__(self, n):
            self.bit = [0] * (n + 1)
            self.n = n

        def sum_prefix(self, i):
            s = 0
            while i > 0:
                s += self.bit[i]
                i -= i & -i
            return s

        def sum_(self, l, r):
            if l == 1:
                return self.sum_prefix(r)
            return self.sum_prefix(r) - self.sum_prefix(l - 1)

        def add(self, i, x):
            while i <= self.n:
                self.bit[i] += x
                i += i & -i
    (n, k, d) = map(int, input().split())
    a = [-1] + list(map(int, input().split()))
    a = sorted(a)
