    def pollard_rho(n):
        """returns a random factor of n"""
        if n & 1 == 0:
            return 2
        if n % 3 == 0:
            return 3
        s = (n - 1 & 1 - n).bit_length() - 1
        d = n >> s
        for a in [2, 325, 9375, 28178, 450775, 9780504, 1795265022]:
            p = pow(a, d, n)
            if p == 1 or p == n - 1 or a % n == 0:
                continue
            for _ in range(s):
                prev = p
                p = p * p % n
                if p == 1:
                    return math.gcd(prev - 1, n)
                if p == n - 1:
                    break
            else:
                for i in range(2, n):
                    (x, y) = (i, (i * i + 1) % n)
                    f = math.gcd(abs(x - y), n)
                    while f == 1:
                        (x, y) = ((x * x + 1) % n, (y * y + 1) % n)
                        y = (y * y + 1) % n
                        f = math.gcd(abs(x - y), n)
                    if f != n:
                        return f
        return n

