        (small, large) = ([], [])
        for i in range(1, int(n ** 0.5) + 1, 2 if n & 1 else 1):
            if not n % i:
                small.append(i)
                large.append(n // i)
        if small[-1] == large[-1]:
            large.pop()
        large.reverse()
        small.extend(large)
        return small

