def _main():

    def readGenerator():
        while True:
            tokens = input().split(' ')
            for t in tokens:
                yield t
    reader = readGenerator()

    def readWord():
        return next(reader)

    def readInt():
        return int(next(reader))

    def readFloat():
        return float(next(reader))

    def readLine():
        return input()

    def createCompression(a, n, k):
        m = deque()
        res = set()
        for i in range(n):
            if len(m) > 0 and m[0][1] < i - k:
                m.popleft()
            while len(m) > 0 and m[-1][0] >= a[i]:
                m.pop()
            m.append((a[i], i))
            if i - k > -1:
                res.add(m[0][0])
        return len(res) == n - k and max(res) == n - k

    def solve(n, a):
        if n == 1:
            return '1' if a[0] == 1 else '0'
        if createCompression(a, n, 1) and createCompression(a, n, 0):
            return '1' * n
        if not createCompression(a, n, n - 1):
            return '0' * n
        s = '1' if createCompression(a, n, 0) else '0'
        l = 0
        r = n - 1
        while r - l > 1:
            mid = (r + l) // 2
            if createCompression(a, n, mid):
                r = mid
            else:
                l = mid
        if createCompression(a, n, l):
            return s + '0' * (l - 1) + '1' * (n - l)
        return s + '0' * (r - 1) + '1' * (n - r)
    t = readInt()
    for _ in range(t):
        n = readInt()
        a = [readInt() for _ in range(n)]
        print(solve(n, a))
