            (u, v) = (self.find(u), self.find(v))
            if u == v:
                return False
            if u.rank > v.rank:
                (u, v) = (v, u)
            u.par = v
            if u.rank == v.rank:
                v.rank += 1
            return True

        def size(self):
            cnt = 0
            for node in self.nodes:
                if node.par == node:
                    cnt += 1
            return cnt

