def _main():

    class DisjointSet(object):

        def __init__(self, n):
            self.parent = list(range(n))
            self.rank = [0] * n
            self.num = n

        def union(self, x, y):
            self._link(self.find_set(x), self.find_set(y))

        def _link(self, x, y):
            if x == y:
                return
            self.num -= 1
            if self.rank[x] > self.rank[y]:
                self.parent[y] = x
            else:
                self.parent[x] = y
                if self.rank[x] == self.rank[y]:
                    self.rank[y] += 1

        def find_set(self, x):
            xp = self.parent[x]
            if xp != x:
                self.parent[x] = self.find_set(xp)
            return self.parent[x]

    def solve():
        (n, m) = map(int, input().split())
        ds = DisjointSet(n * 2)
        for i in range(m):
            (a, b, c) = map(int, input().split())
            a -= 1
            b -= 1
            aA = a * 2
            aB = aA + 1
            bA = b * 2
            bB = bA + 1
            if c == 0:
                if ds.find_set(aA) == ds.find_set(bA):
                    return 0
                ds.union(aA, bB)
                ds.union(aB, bA)
            else:
                if ds.find_set(aA) == ds.find_set(bB):
                    return 0
                ds.union(aA, bA)
                ds.union(aB, bB)
        return pow(2, ds.num // 2 - 1, 10 ** 9 + 7)
    print(solve())
_main()

import os
import sys
from io import BytesIO, IOBase

def _main():

    def main():
        (n, m, k) = map(int, input().split())
        a = list(map(float, input().split()))
        tree = [[0] * n for _ in range(n)]
        for i in range(k):
            (x, y, z) = map(int, input().split())
            tree[x - 1][y - 1] = float(z)
        po = [1]
        while len(po) != n:
            po.append(po[-1] * 2)
        dp = [[0] * (po[-1] * 2) for _ in range(n)]
        for i in range(n):
            dp[i][po[i]] = a[i]
        for i in range(po[-1] * 2):
            for j in range(n):
                if i & po[j]:
                    for k in range(n):
                        if not i & po[k]:
                            dp[k][i + po[k]] = max(dp[k][i + po[k]], dp[j][i] + a[k] + tree[j][k])
        ma = 0
        for i in range(po[-1] * 2):
            if bin(i)[2:].count('1') == m:
                for j in range(n):
                    ma = max(ma, dp[j][i])
        print(int(ma))
    BUFSIZE = 8192

    class FastIO(IOBase):
        newlines = 0

        def __init__(self, file):
            self._fd = file.fileno()
            self.buffer = BytesIO()
            self.writable = 'x' in file.mode or 'r' not in file.mode
            self.write = self.buffer.write if self.writable else None

        def read(self):
            while True:
                b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
                if not b:
                    break
                ptr = self.buffer.tell()
                (self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr))
            self.newlines = 0
            return self.buffer.read()

        def readline(self):
            while self.newlines == 0:
                b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
                self.newlines = b.count(b'\n') + (not b)
                ptr = self.buffer.tell()
                (self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr))
            self.newlines -= 1
            return self.buffer.readline()

        def flush(self):
            if self.writable:
                os.write(self._fd, self.buffer.getvalue())
                (self.buffer.truncate(0), self.buffer.seek(0))

    class IOWrapper(IOBase):

        def __init__(self, file):
            self.buffer = FastIO(file)
            self.flush = self.buffer.flush
            self.writable = self.buffer.writable
            self.write = lambda s: self.buffer.write(s.encode('ascii'))
            self.read = lambda : self.buffer.read().decode('ascii')
            self.readline = lambda : self.buffer.readline().decode('ascii')
    (sys.stdin, sys.stdout) = (IOWrapper(sys.stdin), IOWrapper(sys.stdout))
