def _main():

    def min_route(n, edge_fn):
        t = 0
        s = {1}
        seen = set()
        unseen = set(range(1, n + 1))
        while s:
            seen |= s
            unseen -= s
            ns = set()
            for u in s:
                if u == n:
                    return t
                ns |= {v for v in unseen if edge_fn(u, v)}
            t += 1
            s = ns

    def time(n, r):

        def train(u, v):
            return (u, v) in r or (v, u) in r

        def road(u, v):
            return not train(u, v)
        tt = min_route(n, train)
        tb = min_route(n, road)
        if tt is not None and tb is not None:
            return max(tt, tb)

    def pair(i):
        (u, v) = i
        return (u, v)
    if __name__ == '__main__':
        (n, m) = map(int, input().split())
        r = {pair(map(int, input().split())) for _ in range(m)}
        t = time(n, r)
        print(-1 if t is None else t)
