def _main():

    def bfs(graph, node, inverted, target):
        q = deque()
        q.append(node)
        distance = {}
        distance[node] = 0
        while len(q) > 0:
            current_node = q.popleft()
            if inverted:
                succ = set(range(1, target + 1)) - set(graph[current_node])
            else:
                succ = graph[current_node]
            for children in succ:
                if children not in distance.keys():
                    distance[children] = distance[current_node] + 1
                    q.append(children)
        if target in distance.keys():
            return distance[target]
        return -1
    input_file = sys.stdin
    (nodes, roads) = map(int, input_file.readline().rstrip().split())
    graph = defaultdict(list)
    for line in input_file.readlines():
        (source, target) = map(int, line.rstrip().split())
        graph[source].append(target)
        graph[target].append(source)
    q = deque()
    if nodes in graph[1]:
        print(bfs(graph, 1, True, nodes))
    else:
        print(bfs(graph, 1, False, nodes))
