        return gyaku_kaijo_memo[n]

    class NTT_convolution:

        def __init__(self, ROOT=3, MOD=998244353):
            self.ROOT = 3
            self.MOD = 998244353
            self.roots = [pow(self.ROOT, self.MOD - 1 >> i, self.MOD) for i in range(24)]
            self.iroots = [pow(x, self.MOD - 2, self.MOD) for x in self.roots]

        def untt(self, a, n):
            for i in range(n):
                m = 1 << n - i - 1
                for s in range(1 << i):
                    w_N = 1
                    s *= m * 2
                    for p in range(m):
                        (a[s + p], a[s + p + m]) = ((a[s + p] + a[s + p + m]) % self.MOD, (a[s + p] - a[s + p + m]) * w_N % self.MOD)
                        w_N = w_N * self.roots[n - i] % self.MOD

        def iuntt(self, a, n):
            for i in range(n):
                m = 1 << i
                for s in range(1 << n - i - 1):
                    w_N = 1
                    s *= m * 2
                    for p in range(m):
                        (a[s + p], a[s + p + m]) = ((a[s + p] + a[s + p + m] * w_N) % self.MOD, (a[s + p] - a[s + p + m] * w_N) % self.MOD)
                        w_N = w_N * self.iroots[i + 1] % self.MOD
            inv = pow((self.MOD + 1) // 2, n, self.MOD)
            for i in range(1 << n):
                a[i] = a[i] * inv % self.MOD

        def convolution(self, a, b):
