            if min(la, lb) <= 50:
                if la < lb:
                    (la, lb) = (lb, la)
                    (a, b) = (b, a)
                res = [0] * (la + lb - 1)
                for i in range(la):
                    for j in range(lb):
                        res[i + j] += a[i] * b[j]
                        res[i + j] %= self.MOD
                return res
            N = 1 << n
            a += [0] * (N - len(a))
            b += [0] * (N - len(b))
            self.untt(a, n)
            self.untt(b, n)
            for i in range(N):
                a[i] = a[i] * b[i] % self.MOD
            self.iuntt(a, n)
            return a[:deg + 1]
