    modulo = 1000000007

    def powerMod(base):
        maxp = len(binary_k) - 1
        index = 0
        val = base % modulo
        ret_val = 1
        while index <= maxp:
            if binary_k[index]:
                ret_val = ret_val * val % modulo
            val = val * val % modulo
            index += 1
        return ret_val

    def dfs(vertex):
        stack = [vertex]
        size = 0
        while stack:
            cur = stack.pop()
            marked[cur] = 1
            size += 1
            for child in adj_list[cur]:
                if not marked[child]:
                    stack.append(child)
        return size
    total = powerMod(n)
    for vertex in range(1, n + 1):
        if not marked[vertex]:
            count = dfs(vertex)
            total = (total - powerMod(count)) % modulo
    print(total)
