def _main():
    (left, right) = (0, 1)
    undiscovered = 0
    processed = 1

    def up(state):
        water = state[0] + 1
        point = state[1] + 1
        l_or_r = state[2]
        return [water, point, l_or_r]

    def down(state):
        water = state[0] + 1
        point = state[1] - 1
        l_or_r = state[2]
        return [water, point, l_or_r]

    def jump(state, k):
        water = state[0] + 1
        point = state[1] + k
        if state[2] == left:
            l_or_r = right
        else:
            l_or_r = left
        return [water, point, l_or_r]

    def push_next_states(state, k, states):
        states[len(states):] = [up(state), down(state), jump(state, k)]
        return states

    def solve(n, k, lwall, rwall):
        water = -1
        point = 0
        l_or_r = left
        state = [water, point, l_or_r]
        table = [[undiscovered] * n, [undiscovered] * n]
        states = push_next_states(state, k, [])
        while states != []:
            state = states.pop()
            if state is None:
                break
            water = state[0]
            point = state[1]
            if n <= point:
                return True
            if water < point:
                l_or_r = state[2]
                if table[l_or_r][point] != processed:
                    if l_or_r == left:
                        wall = lwall
                    else:
                        wall = rwall
                    if wall[point] == '-':
                        if n <= point + k:
                            return True
                        push_next_states(state, k, states)
                    table[l_or_r][point] = processed
        return False

    def main():
