            self._E = 0
            self._V = V

        @property
        def E(self):
            return self._E

        @property
        def V(self):
            return self._V

        def add_edge(self, _from, _to, _cost):
            self.G[_from].append(self.Edge(_to, _cost))
            self._E += 1

        def shortest_path(self, s):
            import heapq
            que = []
            d = [10 ** 15] * self.V
            d[s] = 0
            heapq.heappush(que, (0, s))
            while len(que) != 0:
                (cost, v) = heapq.heappop(que)
                if d[v] < cost:
                    continue
                for i in range(len(self.G[v])):
                    e = self.G[v][i]
                    if d[e.to] > d[v] + e.cost:
                        d[e.to] = d[v] + e.cost
                        heapq.heappush(que, (d[e.to], e.to))
            return d

    def Z_algorithm(s):
        N = len(s)
        Z_alg = [0] * N
        Z_alg[0] = N
        i = 1
        j = 0
        while i < N:
            while i + j < N and s[j] == s[i + j]:
                j += 1
            Z_alg[i] = j
            if j == 0:
                i += 1
                continue
            k = 1
            while i + k < N and k + Z_alg[k] < j:
                Z_alg[i + k] = Z_alg[k]
                k += 1
            i += k
            j -= k
        return Z_alg

    class BIT:

        def __init__(self, n, mod=0):
            self.BIT = [0] * (n + 1)
            self.num = n
            self.mod = mod

        def query(self, idx):
            res_sum = 0
            mod = self.mod
            while idx > 0:
                res_sum += self.BIT[idx]
                if mod:
                    res_sum %= mod
                idx -= idx & -idx
            return res_sum

        def update(self, idx, x):
            mod = self.mod
            while idx <= self.num:
                self.BIT[idx] += x
                if mod:
                    self.BIT[idx] %= mod
                idx += idx & -idx
            return

    class dancinglink:

        def __init__(self, n, debug=False):
            self.n = n
            self.debug = debug
            self._left = [i - 1 for i in range(n)]
            self._right = [i + 1 for i in range(n)]
            self.exist = [True for i in range(n)]

        def pop(self, k):
            if self.debug:
                assert self.exist[k]
            L = self._left[k]
            R = self._right[k]
            if L != -1:
                if R != self.n:
                    (self._right[L], self._left[R]) = (R, L)
                else:
                    self._right[L] = self.n
            elif R != self.n:
                self._left[R] = -1
            self.exist[k] = False

        def left(self, idx, k=1):
            if self.debug:
                assert self.exist[idx]
            res = idx
            while k:
                res = self._left[res]
                if res == -1:
                    break
                k -= 1
            return res

        def right(self, idx, k=1):
            if self.debug:
                assert self.exist[idx]
            res = idx
            while k:
                res = self._right[res]
                if res == self.n:
                    break
                k -= 1
            return res

    class SparseTable:

        def __init__(self, A, merge_func, ide_ele):
            N = len(A)
            n = N.bit_length()
            self.table = [[ide_ele for i in range(n)] for i in range(N)]
            self.merge_func = merge_func
            for i in range(N):
                self.table[i][0] = A[i]
            for j in range(1, n):
                for i in range(0, N - 2 ** j + 1):
                    f = self.table[i][j - 1]
                    s = self.table[i + 2 ** (j - 1)][j - 1]
                    self.table[i][j] = self.merge_func(f, s)

        def query(self, s, t):
            b = t - s + 1
            m = b.bit_length() - 1
            return self.merge_func(self.table[s][m], self.table[t - 2 ** m + 1][m])

