            res = self.ide_ele
            l += self.num
            r += self.num
            while l < r:
                if l & 1:
                    res = self.segfunc(res, self.tree[l])
                    l += 1
                if r & 1:
                    res = self.segfunc(res, self.tree[r - 1])
                l >>= 1
                r >>= 1
            return res

        def bisect_l(self, l, r, x):
            l += self.num
            r += self.num
            Lmin = -1
            Rmin = -1
            while l < r:
                if l & 1:
                    if self.tree[l] <= x and Lmin == -1:
                        Lmin = l
                    l += 1
                if r & 1:
                    if self.tree[r - 1] <= x:
                        Rmin = r - 1
                l >>= 1
                r >>= 1
            if Lmin != -1:
                pos = Lmin
                while pos < self.num:
                    if self.tree[2 * pos] <= x:
                        pos = 2 * pos
                    else:
                        pos = 2 * pos + 1
                return pos - self.num
            elif Rmin != -1:
                pos = Rmin
                while pos < self.num:
                    if self.tree[2 * pos] <= x:
                        pos = 2 * pos
                    else:
                        pos = 2 * pos + 1
                return pos - self.num
            else:
                return -1
