    Token = collections.namedtuple('Token', ['type', 'value'])

    def generate_tokens(pattern, text):
        scanner = pattern.scanner(text)
        for m in iter(scanner.match, None):
            token = Token(m.lastgroup, m.group())
            if token.type != 'WS':
                yield token

    def minus(x):
        if x == 0:
            ans = 2
        if x == 1:
            ans = 1
        if x == 2:
            ans = 0
        return ans

    def mult(x, y):
        if x == 0:
