        if x == 1:
            if y == 0:
                a = 0
            if y == 1:
                a = 1
            if y == 2:
                a = 1
        if x == 2:
            if y == 0:
                a = 0
            if y == 1:
                a = 1
            if y == 2:
                a = 2
        return a

