import sys

def _main():
    BORDER = 1 << 30

    def build(x=0):
        high = low = 0
        i = 0
        while x and i < 30:
            if x & 1:
                low += 1 << i
            x >>= 1
            i += 1
        i = 0
        while x:
            if x & 1:
                high += 1 << i
            x >>= 1
            i += 1
        return (high, low)

    def add(x_high, x_low, y_high, y_low):
        x_high += y_high
        x_low += y_low
        if x_low >= BORDER:
            x_low -= BORDER
            x_high += 1
        elif x_low < 0:
            x_low += BORDER
            x_high -= 1
        return (x_high, x_low)
    (n, r, k) = map(int, sys.stdin.buffer.readline().decode('utf-8').split())
    a = list(map(int, sys.stdin.buffer.readline().decode('utf-8').split()))
    (k_high, k_low) = build(k)
    left = build(sum(a[:r]))
    (minus_high, minus_low) = ([0] * n, [0] * n)
    w = 2 * r + 1

    def solve(level_high, level_low):
        used_high = used_low = 0
        (acc_high, acc_low) = left
        for i in range(n):
            if minus_low[i] or minus_high[i]:
                (acc_high, acc_low) = add(acc_high, acc_low, -minus_high[i], -minus_low[i])
                minus_high[i] = minus_low[i] = 0
            (acc_high, acc_low) = add(acc_high, acc_low, 0, (a[i + r] if i + r < n else 0) - (a[i - r - 1] if i - r >= 1 else 0))
            if acc_high < level_high or (acc_high == level_high and acc_low < level_low):
                (used_high, used_low) = add(used_high, used_low, level_high - acc_high, level_low - acc_low)
                if used_high > k_high or (used_high == k_high and used_low > k_low):
                    break
                if i + w < n:
                    minus_high[i + w] = level_high - acc_high
                    minus_low[i + w] = level_low - acc_low
                acc_high = level_high
                acc_low = level_low
        for i in range(i + 1, n):
            if minus_low[i] or minus_high[i]:
                minus_low[i] = minus_high[i] = 0
        return used_high < k_high or (used_high == k_high and used_low <= k_low)
    (ok, ng) = (min(a) + k // n, k + sum(a) + 1)
    while abs(ok - ng) > 1:
        mid = ok + ng >> 1
        if solve(*build(mid)):
            ok = mid
        else:
            ng = mid
    print(ok)
