    def ItoS(n):
        return chr(n + 97)

    def LtoS(ls):
        return ''.join([chr(i + 97) for i in ls])

    def GI(V, E, ls=None, Directed=False, index=1):
        org_inp = []
        g = [[] for i in range(V)]
        FromStdin = True if ls == None else False
        for i in range(E):
            if FromStdin:
                inp = LI()
                org_inp.append(inp)
            else:
                inp = ls[i]
            if len(inp) == 2:
                (a, b) = inp
                c = 1
            else:
                (a, b, c) = inp
            if index == 1:
                a -= 1
                b -= 1
            aa = (a, c)
            bb = (b, c)
            g[a].append(bb)
            if not Directed:
                g[b].append(aa)
        return (g, org_inp)

    def GGI(h, w, search=None, replacement_of_found='.', mp_def={'#': 1, '.': 0}, boundary=1):
        mp = [boundary] * (w + 2)
        found = {}
        for i in range(h):
            s = input()
            for char in search:
                if char in s:
                    found[char] = (i + 1) * (w + 2) + s.index(char) + 1
                    mp_def[char] = mp_def[replacement_of_found]
            mp += [boundary] + [mp_def[j] for j in s] + [boundary]
        mp += [boundary] * (w + 2)
        return (h + 2, w + 2, mp, found)

