    def prod(n):
        if n % 2:
            return n * ((n + 1) // 2)
        else:
            return n // 2 * (n + 1)

    def total_count(n, k):
        if k >= n:
            return (0, 0, 1)
        else:
            count = 0
            l = 1
            r = k
            s = prod(k)
            while l <= r:
