    def solve():
        MOD = 10 ** 9 + 7
        N = int(readline())
        S = []
        for i in range(N):
            s = readline().strip()
            if s == '-':
                N -= 1
                continue
            S.append(s == 'D')
        memo = {}

        def dfs(i, a, b):
            if i == N:
                return a == b == 0
            key = (i, a, b)
            if key in memo:
                return memo[key]
            r = 0
            if S[i]:
                if a > 0:
                    r += dfs(i + 1, a, b) * a % MOD
                if a > 0 and b > 0:
                    r += dfs(i + 1, a - 1, b - 1) * a * b % MOD
            else:
                r += dfs(i + 1, a + 1, b + 1)
                if b > 0:
                    r += dfs(i + 1, a, b) * b % MOD
            memo[key] = r = r % MOD
            return r
        write('%d\n' % dfs(0, 0, 0))
    solve()
