        for i in range(2, math.floor(math.sqrt(n + 1) + 0.5)):
            p = 0
            while n % i == 0:
                n //= i
                p += 1
            if p > 0:
                yield (i, p)
        if n > 1:
            yield (n, 1)

    def factors(n, p=None, i=0, r=[], b=1):
        if p == None:
            p = list(pfactors(n))
