            for x in range(0, p[i][1] + 1):
                factors(n, p, i + 1, r, b)
                b *= p[i][0]
        else:
            r.append(b)
        if i == 0:
            return r

    def factors2(n):
        large_divisors = []
        for i in range(1, int(math.sqrt(n) + 1)):
            if n % i == 0:
                yield i
                if i * i != n:
                    large_divisors.append(n // i)
        for divisor in reversed(large_divisors):
            yield divisor

    def f(k):
        p = k
        x = n // p
        return (2 + (x - 1) * k) * x // 2
