            return x / 2 if x % 2 == 0 else x
        return f

    def lcd(numbers):
        gcd = lambda x, y: int(x) if y == 0 else int(gcd(y, x % y))
        ret = 1
        for number in numbers:
            ret = ret * number / gcd(ret, number)
        return ret

