    import math

    def ncr(n, r):
        p = 1
        k = 1
        if n - r < r:
            r = n - r
        if r != 0:
            while r > 0:
                p *= n
                k *= r
                m = math.gcd(p, k)
                p //= m
                k //= m
                n -= 1
                r -= 1
        else:
            p = 1
        return p
