    def ncr(n, r, p):
        num = den = 1
        for i in range(r):
            num = num * (n - i) % p
            den = den * (i + 1) % p
        return num * pow(den, p - 2, p) % p

    def primeFactors(n):
        l = []
        while n % 2 == 0:
            l.append(2)
            n = n / 2
        for i in range(3, int(math.sqrt(n)) + 1, 2):
            while n % i == 0:
                l.append(int(i))
                n = n / i
        if n > 2:
