def _main():
    (H, W, K) = map(int, input().split())
    MOD = 10 ** 9 + 7
    if W == 1:
        print(1)
        exit()
    possible = []
    for i in range(1 << W - 1):
        b = bin(i)[2:]
        flag = 1
        for j in range(len(b) - 1):
            if b[j] == b[j + 1] == '1':
                flag = 0
        if flag:
            possible.append(int(b, 2))

    def amida(b):
        ret = [i for i in range(W)]
        for i in range(W - 1):
            if b >> i & 1:
                (ret[i], ret[i + 1]) = (ret[i + 1], ret[i])
        return ret
    ans = [0 for i in range(W)]
    ans[0] = 1
    for _ in range(H):
        new_ans = [0 for i in range(W)]
        for b in possible:
            for i in range(W):
                new_ans[i] = (new_ans[i] + ans[amida(b)[i]]) % MOD
        ans = new_ans
    print(ans[K - 1])
_main()

from itertools import product

def _main():
    (H, W, K) = map(int, input().split())
    mod = 10 ** 9 + 7
    dp = [[0] * W for _ in range(H + 1)]
    dp[0][0] = 1
    for (i, j, k) in product(range(H), range(W), range(1 << W - 1)):
        ok = True
        for l in range(W - 2):
            if k >> l & 1 and k >> l + 1 & 1:
                ok = False
        if not ok:
            continue
        if j >= 1 and k >> j - 1 & 1:
            dp[i + 1][j - 1] += dp[i][j]
            dp[i + 1][j - 1] %= mod
        elif j <= W - 2 and k >> j & 1:
            dp[i + 1][j + 1] += dp[i][j]
            dp[i + 1][j + 1] %= mod
        else:
            dp[i + 1][j] += dp[i][j]
            dp[i + 1][j] %= mod
    print(dp[H][K - 1])
_main()

