                if s & 1 ^ 1:
                    return False
            return True
        is_good_table = [[is_good(m1, m2) for m2 in range(max_mask)] for m1 in range(max_mask)]
        count_differ_table = [[binary_count_1(mask_differ(m1, m2)) for m2 in range(max_mask)] for m1 in range(max_mask)]
        mask1 = to_binary(g[0])
