    def bisect_left(a, x):
        """i tale che a[i] >= x e a[i-1] < x"""
        left = 0
        right = len(a)
        while left < right:
            mid = (left + right) // 2
            if a[mid] < x:
                left = mid + 1
            else:
                right = mid
        return left

    def bisect_right(a, x):
        """i tale che a[i] > x e a[i-1] <= x"""
        left = 0
        right = len(a)
        while left < right:
            mid = (left + right) // 2
            if a[mid] > x:
                right = mid
            else:
                left = mid + 1
        return left

    def bisect_elements(a, x):
        """elementi pari a x nell'árray sortato"""
        return bisect_right(a, x) - bisect_left(a, x)
