    def dist(tree, n, A, B=-1):
        s = [[A, 0]]
        (massimo, massimo_nodo) = (0, 0)
        distanza = -1
        v = [-1] * n
        while s:
            (el, dis) = s.pop()
            if dis > massimo:
                massimo = dis
                massimo_nodo = el
            if el == B:
                distanza = dis
            for child in tree[el]:
                if v[child] == -1:
                    v[child] = 1
                    s.append([child, dis + 1])
        return (massimo, massimo_nodo, distanza)

    def diameter(tree):
