    class BitSum:

        def __init__(self, n):
            self.n = n + 1
            self.table = [0] * self.n

        def add(self, i, x):
            i += 1
            while i < self.n:
                self.table[i] += x
                i += i & -i

        def sum(self, i):
            i += 1
            res = 0
            while i > 0:
                res += self.table[i]
                i -= i & -i
