import random
from math import ceil, sqrt, gcd, floor

def _main():

    def solve_1(n):
        smallest = []
        for i in range(2, n + 1):
            min_imp = [999999999999999999999] * 1
            combination(n, [0] * i, 0, 1, min_imp, [0] * n)
            smallest.append(min_imp[0])
        return smallest

    def combination(n, c, pos, l, min_imp, mark):
        if pos == len(c):
            imperfection = 1
            for i in range(len(c)):
                for j in range(len(c)):
                    if c[i] != c[j]:
                        imperfection = max(imperfection, gcd(c[i], c[j]))
            min_imp[0] = min(imperfection, min_imp[0])
            return
        for i in range(l, n + 1):
            if mark[i - 1] != 1:
                c[pos] = i
                mark[i - 1] = 1
                combination(n, c, pos + 1, c[pos] + 1, min_imp, mark)
                mark[i - 1] = 0
        return

    def solve_2(n):
        gd = [0] * (n - 1)
        for i in range(2, n + 1):
            gd[i - 2] = greatest_divisor_2(i)
        merge_sort(gd, 0, len(gd) - 1, [0] * len(gd))
        return gd

    def greatest_divisor_1(n):
        d = 1
        for i in range(1, ceil(n / 2) + 1):
            if n % i == 0:
                d = i
        return d

    def greatest_divisor_2(n):
        d = 1
        for i in range(2, int(sqrt(n) + 1)):
            if n % i == 0:
                d = n // i
                break
        return d

    def merge_sort(A, l, r, B):
        if l < r:
            m = (r + l) // 2
            merge_sort(A, l, m, B)
            merge_sort(A, m + 1, r, B)
            merge(A, l, r, B)
        return

    def merge(A, l, r, B):
        m = (r + l) // 2
        (k, p, q) = (l, l, m + 1)
        while p <= m and q <= r:
            if A[p] < A[q]:
                B[k] = A[p]
                p += 1
            else:
                B[k] = A[q]
                q += 1
            k += 1
        while p <= m:
            B[k] = A[p]
            k += 1
            p += 1
        while q <= r:
            B[k] = A[q]
            k += 1
            q += 1
        for i in range(l, r + 1):
            A[i] = B[i]
        return

    def solve_3(n):
        gd = sieve(n)
        merge_sort(gd, 0, len(gd) - 1, [0] * len(gd))
        return gd

    def sieve(n):
        gd = [1] * (n - 1)
        sieve = [False] * (n - 1)
        for i in range(2, floor(sqrt(n)) + 1):
            if not sieve[i - 2]:
                for j in range(i, n // i + 1):
                    sieve[i * j - 2] = True
                    gd[i * j - 2] = max(gd[i * j - 2], i, j)
        return gd

    def main():
        n = int(input())
        print(' '.join((str(i) for i in solve_3(n))))
        return

