import math

def _main():

    def read_data():
        return tuple(map(int, next(sys.stdin).split()))

    def reverse_count(k):
        d = math.sqrt(1 + 8 * k)
        n = int((1 + d) / 2 + 0.5)
        if n * (n - 1) == 2 * k:
            return n
        return None

    def solve1(a, b, x01, x10):
        if x01 + x10 != a * b:
            return None
        characters = []
        while a > 0 or b > 0:
            if a >= 1 and x01 >= b:
                a -= 1
                x01 -= b
                characters.append('0')
            elif b >= 1 and x10 >= a:
                b -= 1
                x10 -= a
                characters.append('1')
            else:
                return None
        return ''.join(characters)

    def solve(x00, x01, x10, x11):
        if x00 == 0:
            if x11 == 0:
                if x01 == x10 == 0:
                    return '0'
                return solve1(1, 1, x01, x10)
            b = reverse_count(x11)
            if b is not None:
                return solve1(0, b, x01, x10) or solve1(1, b, x01, x10)
            return None
        if x11 == 0:
            a = reverse_count(x00)
            if a is not None:
                return solve1(a, 0, x01, x10) or solve1(a, 1, x01, x10)
            return None
        a = reverse_count(x00)
        b = reverse_count(x11)
        if a is not None and b is not None:
            return solve1(a, b, x01, x10)
        return None
    if __name__ == '__main__':
        (x00, x01, x10, x11) = read_data()
        s = solve(x00, x01, x10, x11)
        if s is None:
            print('Impossible')
        else:
            print(s)
