def _main():
    n = int(input())

    def find(n):
        (y, x) = (-1, 10000000000000)
        while y + 1 != x:
            m = (y + x) // 2
            if con(m) >= n:
                x = m
            else:
                y = m
        return str(x)[n - con(y) - 1]

    def con(x):
        (s, q, z) = (0, 1, 0)
        while x != 0:
            z = min(x, 9 * 10 ** (q - 1))
            x = x - z
            s += z * q
            q += 1
        return s
    print(find(n))
_main()

