    def find_minimum_divisors(M):
        res = set([])
        for i in range(1, M + 1):
            if i * i > M:
                break
            if M % i == 0:
                res.add(i)
                res.add(M // i)
        res.remove(1)
        return list(res)

    def slv():
        n = int(input())
