        final_ans = 1 << 128
        for div in find_minimum_divisors(len(b)):
            B = b.copy()
            ans = 0
            for _ in range(len(b) // div):
                array = []
                for _ in range(div):
                    array.append(B.popleft())
                cost = sum(array) - array[0] * div
                tmpmincost = cost
                for i in range(div - 1):
                    d = array[i + 1] - array[i]
                    cost += (2 * (i + 1) - div) * d
                    tmpmincost = min(tmpmincost, cost)
                    assert tmpmincost >= 0
                ans += tmpmincost
            final_ans = min(final_ans, ans)
        print(final_ans)
