def _main():
    M = 10 ** 6

    def sieve_of_eratosthenes(limit, typecode='L'):
        table = array.array('B', (True for i in range(limit)))
        table[0] = False
        table[1] = False
        for i in range(2, limit):
            if table[i]:
                for j in range(i * 2, limit, i):
                    table[j] = False
        return table

    def solve(table, a, d, n):
        primes = collections.deque()
        for i in range(a, M, d):
            if table[i]:
                primes.append(i)
                if len(primes) >= n:
                    break
        return primes[-1]
    if __name__ == '__main__':
        table = sieve_of_eratosthenes(M)
        while True:
            (a, d, n) = map(int, input().split())
            if a == d == n == 0:
