        last = [-1] * (n + 1)
        (i, j) = (0, -1)
        while i < n:
            while j != -1 and s[i] != s[j]:
                j = last[j]
            (i, j) = (i + 1, j + 1)
            last[i] = j
        return last

    def kmp(p, t, last):
        m = len(p)
        n = len(t)
        i = j = 0
        rl = []
        while i < n:
            while j != -1 and t[i] != p[j]:
                j = last[j]
            (i, j) = (i + 1, j + 1)
            if j >= m:
                rl.append(i)
                j = last[j]
        return rl

