    for i in range(d):
        (x1, y1, x2, y2) = map(int, input().strip().split())
        if x1 == x2:
            Hxds[x1 - 1] += 1
            Hyds[min(y1, y2) - 1] += 1
            ds.append((x1 - 1, min(y1, y2) - 1, 'h'))
        else:
            Vxds[min(x1, x2) - 1] += 1
            Vyds[y1 - 1] += 1
            ds.append((min(x1, x2) - 1, y1 - 1, 'v'))
