import sys

def _main():
    sys.setrecursionlimit(10 ** 6)

    class LinkedList:

        def __init__(self, n):
            self.n = n
            self.ll = [[] for _ in range(self.n)]

        def link(self, u, v, direction=False):
            self.ll[u].append(v)
            if not direction:
                self.ll[v].append(u)

        def dfs(self):
            self.cc = [None] * self.n
            color = 1
            for u in range(self.n):
                if not self.cc[u]:
                    self.dfs_visit(u, color)
                    color += 1

        def dfs_visit(self, u, color):
            self.cc[u] = color
            for v in self.ll[u]:
                if not self.cc[v]:
                    self.dfs_visit(v, color)

        def check(self, u, v):
            if self.cc[u] == self.cc[v]:
                print('yes')
            else:
                print('no')
    if __name__ == '__main__':
        (n, m) = map(int, input().split())
        ll = LinkedList(n)
        for _ in range(m):
            (u, v) = map(int, input().split())
            ll.link(u, v)
        ll.dfs()
        q = int(input())
        for _ in range(q):
            (u, v) = map(int, input().split())
