    class UnionFind:

        def __init__(self, n):
            self.parent = [i for i in range(n + 1)]
            self.rank = [0] * (n + 1)

        def find(self, x):
            if self.parent[x] == x:
                return x
            else:
                self.parent[x] = self.find(self.parent[x])
                return self.parent[x]

        def is_same_tree(self, x, y):
            return self.find(x) == self.find(y)

        def union(self, x, y):
            x = self.find(x)
            y = self.find(y)
            if self.rank[x] < self.rank[y]:
                self.parent[x] = y
            else:
                self.parent[y] = x
            if self.rank[x] == self.rank[y]:
                self.rank[x] += 1

