    def solve(rows):
        all_dists = [0 for _ in range(len(rows[0]))]
        for r in rows:
            dists = [len(r) for _ in r]
            if '1' not in r:
                return -1
            start = r.index('1')
            for i in range(len(r)):
                right = (i + start) % len(r)
                left = (start + 2 * len(r) - i) % len(r)
                dists[right] = 0 if r[right] == '1' else min(dists[right], dists[(i + start - 1) % len(r)] + 1)
