def _main():

    class DisjointSet:

        def __init__(self, n):
            self.num_sets = n
            self.parents = list(range(n))
            self.ranks = [0] * n
            self.sizes = [1] * n

        def find(self, j):
            while self.parents[j] != j:
                j = self.parents[j]
            return j

        def union(self, i, j):
            i = self.find(i)
            j = self.find(j)
            if i == j:
                return False
            rd = self.ranks[i] - self.ranks[j]
            if rd == 0:
                self.ranks[i] += 1
            elif rd < 0:
                (i, j) = (j, i)
            self.parents[j] = i
            self.sizes[i] += self.sizes[j]
            self.sizes[j] = 0
            self.num_sets -= 1
            return True

    def main():
