    (n, m, k) = list(map(int, input().split()))
    a = list(map(int, input().split()))
    p_a = [0 for _ in range(n)]
    p_a[0] = a[0]
    for i in range(1, n):
        p_a[i] = p_a[i - 1] + a[i]
    INF = -10000000000.0
    dp = {}
    from types import GeneratorType

    def bootstrap(f, stack=[]):

        def wrappedfunc(*args, **kwargs):
            if stack:
                return f(*args, **kwargs)
            else:
                to = f(*args, **kwargs)
                while True:
                    if type(to) is GeneratorType:
                        stack.append(to)
                        to = next(to)
                    else:
                        stack.pop()
                        if not stack:
                            break
                        to = stack[-1].send(to)
                return to
        return wrappedfunc

    @bootstrap
    def solve(i, k, m):
        if (i, k, m) in dp:
            yield dp[i, k, m]
        if k == 0:
            dp[i, k, m] = 0
            yield 0
        if i + m == n:
            if k == 1:
                if i == 0:
                    dp[i, k, m] = p_a[n - 1]
                else:
                    dp[i, k, m] = p_a[n - 1] - p_a[i - 1]
                yield dp[i, k, m]
            if k > 1:
                dp[i, k, m] = INF
                yield INF
        if i + m > n - 1:
            dp[i, k, m] = INF
            yield INF
        if k == 0:
            dp[i, k, m] = 0
            yield 0
        if i == 0:
            a = (yield solve(i + 1, k, m))
            b = (yield solve(i + m, k - 1, m))
            dp[i, k, m] = max(a, b + p_a[i + m - 1])
            yield dp[i, k, m]
        else:
            a = (yield solve(i + 1, k, m))
            b = (yield solve(i + m, k - 1, m))
            dp[i, k, m] = max(a, b + p_a[i + m - 1] - p_a[i - 1])
            yield dp[i, k, m]
    if m == 1:
        print(sum(sorted(a)[n - k:]))
    else:
        print(solve(0, k, m))
