    WHOLE_INVERSION = 0
    fenwick_1 = fenwick(n)
    for (value, index) in seq:
        WHOLE_INVERSION += fenwick_1.get(1, index)
        fenwick_1.add(index, 1)
    for (l, r) in query:
        d = r - l + 1
        WHOLE_INVERSION += d * (d - 1) // 2
        if WHOLE_INVERSION % 2 != 0:
