def _main():

    def search_podstroki(s, t):
        t1 = t + '$' + s
        p = [-1] * len(t1)
        prefix(t1, p)
        c1 = 0
        for i in range(1, len(t1)):
            if p[i] == len(t) - 1:
                c1 = -1
                return i - len(t) - 1
        if c1 != -1:
            return False

    def prefix(t, p):
        k = 0
        for i in range(1, len(t)):
            k = p[i - 1]
            while k >= 0 and t[k + 1] != t[i]:
                k = p[k]
            if t[k + 1] == t[i]:
                k = k + 1
            p[i] = k
    s = input()
    s1 = 'AB'
    s2 = 'BA'
    r = search_podstroki(s, s1)
    if r == False:
        print('NO')
    else:
        s3 = s[r + 1:]
        e = search_podstroki(s3, s2)
        if e == False:
            r = search_podstroki(s, s2)
            if r == False:
                print('NO')
            else:
                s3 = s[r + 1:]
                e = search_podstroki(s3, s1)
                if e == False:
                    print('NO')
                else:
                    print('YES')
        else:
            print('YES')
