                    return 0
                else:
                    for i in son_tree[node]:
                        dfs(i)
                    dp[node] = sum((dp[k] for k in son_tree[node]))
                    return 0
        dfs(1)
        print(leaf_ctr - dp[1] + 1)
    if __name__ == '__main__':
        t = threading.Thread(target=main)
        t.start()
        t.join()
