    class Dijkstra:

        class Edge:

            def __init__(self, _to, _cost):
                self.to = _to
                self.cost = _cost

        def __init__(self, V):
            self.G = [[] for i in range(V)]
            self._E = 0
            self._V = V

        @property
        def E(self):
            return self._E

        @property
        def V(self):
            return self._V

        def add_edge(self, _from, _to, _cost):
            self.G[_from].append(self.Edge(_to, _cost))
            self._E += 1

        def shortest_path(self, s):
            import heapq
            que = []
            d = [10 ** 15] * self.V
            d[s] = 0
            heapq.heappush(que, (0, s))
            while len(que) != 0:
                (cost, v) = heapq.heappop(que)
                if d[v] < cost:
                    continue
                for i in range(len(self.G[v])):
                    e = self.G[v][i]
                    if d[e.to] > d[v] + e.cost:
                        d[e.to] = d[v] + e.cost
                        heapq.heappush(que, (d[e.to], e.to))
            return d

    def Z_algorithm(s):
        N = len(s)
        Z_alg = [0] * N
        Z_alg[0] = N
        i = 1
        j = 0
        while i < N:
            while i + j < N and s[j] == s[i + j]:
                j += 1
            Z_alg[i] = j
            if j == 0:
                i += 1
                continue
            k = 1
            while i + k < N and k + Z_alg[k] < j:
                Z_alg[i + k] = Z_alg[k]
                k += 1
            i += k
            j -= k
        return Z_alg

