        def get(self, u):
            if u != self.p[u]:
                self.p[u] = self.get(self.p[u])
            return self.p[u]

        def union(self, u, v):
            u = self.get(u)
            v = self.get(v)
            if u != v:
                if self.r[u] > self.r[v]:
                    (u, v) = (v, u)
                self.p[u] = v
                if self.r[u] == self.r[v]:
                    self.r[v] += 1
                self.s[v] += self.s[u]

