    class DisjointSet(object):

        def __init__(self, n):
            self.n = n
            self.set_lists = [[i] for i in range(n)]
            self.set = [i for i in range(n)]

        def find(self, u):
            return self.set[u]

        def unite(self, u, v):
            (u_set, v_set) = (self.find(u), self.find(v))
            if u_set == v_set:
                return False
            if len(self.set_lists[u_set]) > len(self.set_lists[v_set]):
                (u_set, v_set) = (v_set, u_set)
            for i in self.set_lists[u_set]:
                self.set_lists[v_set].append(i)
                self.set[i] = v_set
            return True

        def get_count(self):
            count = 0
            for i in range(self.n):
                if self.set[i] == i:
                    count += 1
            return count

    def solve(n, points):
        assert len(points) == n
        dsu = DisjointSet(n)
        for i in range(n):
            for j in range(i + 1, n):
                if points[i][0] == points[j][0] or points[i][1] == points[j][1]:
                    dsu.unite(i, j)
        return dsu.get_count() - 1
    n = int(input())
