def _main():

    def and_i(i):
        return i & i + 1

    def or_i(i):
        return i | i + 1

    class Tree:

        def __init__(self, n):
            self.n = n
            self.tree = [0] * n

        def get_sum(self, i):
            ans = 0
            while i >= 0:
                ans += self.tree[i]
                i = and_i(i) - 1
            return ans

        def update_tree(self, i, x=1):
            while i < self.n:
                self.tree[i] += x
                i = or_i(i)
    n = int(input())
