        l = 0
        r = len(t) - 1
        while l <= r:
            m = (l + r) // 2
            if t[m][0] >= x:
                r = m - 1
            else:
                l = m + 1
        return r

    def distFrom(point, xPos):
        (x1, y1) = (xPos, 0)
        (x2, y2) = point
        return abs(x2 - x1) ** 2 + abs(y2 - y1) ** 2

