def _main():

    def topological_sort(E, D):
        D = D[:]
        n = len(E)
        Q = [i for i in range(n) if D[i] == 0]
        L = []
        while Q:
            p = Q.pop()
            L.append(p)
            for vf in E[p]:
                D[vf] -= 1
                if not D[vf]:
                    Q.append(vf)
        if len(L) != n:
            return False
        return L
    N = int(input())
    wsv = [list(map(int, input().split())) for _ in range(N)]
    (W, S, V) = map(list, zip(*wsv))
    Edge = [[] for _ in range(N)]
    Dim = [0] * N
    for i in range(N):
        for j in range(N):
            m1 = min(S[j], S[i] - W[j])
            m2 = min(S[i], S[j] - W[i])
            if m1 == m2:
                continue
            if m1 < m2:
                Edge[i].append(j)
                Dim[j] += 1
            else:
                Edge[j].append(i)
                Dim[i] += 1
    L = topological_sort(Edge, Dim)
    dp = Counter()
    dp[10 ** 9 + 7] = 0
    for l in L[::-1]:
        for (k, v) in dp.copy().items():
            if k >= W[l]:
                t = min(k - W[l], S[l])
