from collections import deque
import heapq

def _main():
    (N, M, K, S) = map(int, input().split())
    (P, Q) = map(int, input().split())
    C = []
    for _ in range(K):
        C.append(int(input()))
    adj = [[] for _ in range(N + 1)]
    for _ in range(M):
        (a, b) = map(int, input().split())
        adj[a].append(b)
        adj[b].append(a)
    expensive_cities = set()
    for c in C:
        q = deque([c])
        step = 0
        visited = [False] * (N + 1)
        while q and step <= S:
            l = len(q)
            new_q = deque()
            for _ in range(l):
                node = q.popleft()
                visited[node] = True
                for nei in adj[node]:
                    if visited[nei]:
                        continue
                    if nei in q or nei in new_q:
                        continue
                    if nei in C:
                        continue
                    new_q.append(nei)
            q = new_q
            step += 1
        for i in range(1, N + 1):
            if visited[i] and i not in C:
                expensive_cities.add(i)
    adj2 = [[] for _ in range(N + 1)]
    for i in range(1, N + 1):
        for city in adj[i]:
            if city in C:
                continue
            if city in expensive_cities:
                adj2[i].append((city, Q))
            else:
                adj2[i].append((city, P))
    pq = [(0, 1)]
    dist = [float('inf')] * (N + 1)
    visited = [False] * (N + 1)
    dist[1] = 0
    while pq:
        (d, n) = heapq.heappop(pq)
        if n == N:
            break
        visited[n] = True
        for (nei, nd) in adj2[n]:
            if visited[nei]:
                continue
            if d + nd < dist[nei]:
                dist[nei] = d + nd
                heapq.heappush(pq, (d + nd, nei))
    d = dist[N]
    if N in expensive_cities:
        print(d - Q)
    else:
        print(d - P)
_main()

from heapq import heappush, heappop

def _main():
    INF = 10 ** 20
    (n, m, k, s) = map(int, input().split())
    (p, q) = map(int, input().split())
    z_dist = [INF] * n
    que = []
    for _ in range(k):
        c = int(input()) - 1
        z_dist[c] = 0
        heappush(que, (0, c))
    edges = [[] for _ in range(n)]
    for _ in range(m):
        (a, b) = map(int, input().split())
        a -= 1
        b -= 1
        edges[a].append(b)
        edges[b].append(a)
    while que:
        (total, node) = heappop(que)
        for to in edges[node]:
            if z_dist[to] > total + 1:
                z_dist[to] = total + 1
                heappush(que, (total + 1, to))
    cost = [INF] * n
    cost[0] = 0
    que = []
    heappush(que, (0, 0))
    while que:
        (total, node) = heappop(que)
        for to in edges[node]:
            if to == n - 1:
                if cost[to] > total:
                    cost[to] = total
                    continue
            if z_dist[to] == 0:
                continue
            if z_dist[to] <= s:
                price = q
            else:
                price = p
            if cost[to] > total + price:
                cost[to] = total + price
                heappush(que, (total + price, to))
    print(cost[n - 1])
