                if x - 1 in temp:
                    temp.add(x)
                elif x - 1 != 0:
                    temp.add(x - 1)
                else:
                    temp.add(x)
            elif dic[x] == 2:
                if x - 1 in temp:
                    temp.add(x)
                    temp.add(x + 1)
                    dic[x + 1] += 1
                else:
