    class UnionFind:

        def __init__(self, n):
            self.parent = list(range(n))
            self.size = [1] * n
            self.num_sets = n

        def find(self, a):
            to_update = []
            while a != self.parent[a]:
                to_update.append(a)
                a = self.parent[a]
            for b in to_update:
                self.parent[b] = a
            return self.parent[a]

        def merge(self, a, b):
            a = self.find(a)
            b = self.find(b)
            if a == b:
                return
            if self.size[a] < self.size[b]:
                (a, b) = (b, a)
            self.num_sets -= 1
            self.parent[b] = a
            self.size[a] += self.size[b]

        def set_size(self, a):
            return self.size[self.find(a)]

        def __len__(self):
            return self.num_sets

    def bisect_left(a, x):
        """i tale che a[i] >= x e a[i-1] < x"""
        left = 0
        right = len(a)
        while left < right:
            mid = (left + right) // 2
            if a[mid] < x:
                left = mid + 1
            else:
                right = mid
        return left

    def bisect_right(a, x):
        """i tale che a[i] > x e a[i-1] <= x"""
        left = 0
        right = len(a)
        while left < right:
            mid = (left + right) // 2
            if a[mid] > x:
                right = mid
            else:
                left = mid + 1
        return left

    def bisect_elements(a, x):
        """elementi pari a x nell'árray sortato"""
