                idx = i
                start_pair = [0, s[i] if i % 2 == 0 else str(1 - int(s[i]))]
                break
        if start_pair[0] == -1:
            print(n * (n + 1) // 2)
            return
        current_pair = start_pair.copy()
        for (idx, i) in enumerate(s):
            if i in '01':
                if (idx - current_pair[0]) % 2 and i != current_pair[1] or ((idx - current_pair[0]) % 2 == 0 and i == current_pair[1]):
                    (current_pair[0], current_pair[1]) = (idx, i)
                else:
                    length = idx - start_pair[0]
                    ans += length * (length + 1) // 2
                    (start_pair[0], start_pair[1]) = (current_pair[0] + 1, current_pair[1])
                    overlap = idx - current_pair[0] - 1
                    ans -= overlap * (overlap + 1) // 2
                    (current_pair[0], current_pair[1]) = (idx, i)
        length = n - start_pair[0]
