    def binary(arraySum, n, value):
        (low, high) = (0, n)
        while low <= high:
            mid = (low + high) // 2
            if arraySum[mid] == value:
                return mid
            elif arraySum[mid] > value:
                high = mid - 1
            else:
                low = mid + 1
        return high

