    class segmenttree:

        def __init__(self, arr, n):
            (self.tree, self.n) = ([0] * (2 * n), n)
            if arr:
                for i in range(2 * n - 1, 0, -1):
                    if i >= n:
                        self.tree[i] = arr[i - n]
                    else:
                        self.tree[i] = self.tree[i << 1] + self.tree[(i << 1) + 1]

        def query(self, l, r):
            res = 0
            l += self.n
            r += self.n
            while l < r:
                if l & 1:
                    res += self.tree[l]
                    l += 1
                if r & 1:
                    r -= 1
                    res += self.tree[r]
                l >>= 1
                r >>= 1
            return res

        def update(self, ix, val):
            ix += self.n
            self.tree[ix] = val
            while ix > 1:
                self.tree[ix >> 1] = self.tree[ix] + self.tree[ix ^ 1]
                ix >>= 1
    (cum, all) = (defaultdict(int), [])
