def _main():

    def erase(array, i, N):
        if array[i - 1] == array[i]:
            up = i - 1
            down = i
        elif array[i] == array[i + 1]:
            up = i
            down = i + 1
        else:
            return N - 2
        while True:
            if array[up] == -1 or array[down] == -1 or (not array[up] == array[down]):
                return up + N - down - 1
            save_up = up
            save_down = down
            c = array[up]
            while array[up] == c:
                up -= 1
            while array[down] == c:
                down += 1
            if save_up - up + down - save_down < 4:
                return save_up + N - save_down - 1

    def main():
        while True:
            N = int(input())
            if N == 0:
