            min_erased = N
            for i in range(1, N + 1):
                save = a[i]
                a[i] = save % 3 + 1
                min_erased = min(min_erased, erase(a, i, N + 2))
                a[i] = (save + 1) % 3 + 1
                min_erased = min(min_erased, erase(a, i, N + 2))
                a[i] = save
            print(min_erased)
