                idx >>= 1

        def __len__(self):
            return self._len

        def query(self, start, stop):
            if start == stop:
                return self.__getitem__(start)
            stop += 1
            start += self._size
            stop += self._size
            res = self._default
            while start < stop:
                if start & 1:
                    res = self._func(res, self.data[start])
                    start += 1
                if stop & 1:
                    stop -= 1
                    res = self._func(res, self.data[stop])
                start >>= 1
                stop >>= 1
            return res

