            gx = self.find_root(x)
            gy = self.find_root(y)
            if gx == gy:
                return
            self.group -= 1
            if self._size[gx] < self._size[gy]:
                self._parent[gx] = gy
                self._size[gy] += self._size[gx]
            else:
                self._parent[gy] = gx
                self._size[gx] += self._size[gy]

        def get_size(self, x):
