        for i in range(level):
            if diff >> i & 1:
                v = parent[v][i]
        if u == v:
            return u
        i = level - 1
        while i >= 0:
            if parent[u][i] != parent[v][i]:
                u = parent[u][i]
                v = parent[v][i]
            i += -1
        return parent[u][0]

